import React, { useState, useEffect, ChangeEvent, FormEvent } from "react";
import api from "../api/axios";
import axios from "axios";
import { useNavigate, useParams, Link } from "react-router-dom";
import Loading from "../Components/Loading";
import ShopSelect from "../Components/ShopSelect"; 
import styles from "../styles/MemberPage/MemberEdit.module.css"; 

interface Member {
  employee_no: number;
  name: string;
  shop: string;
  authority: boolean;
  administrator: boolean;
  break_time1: string;
  break_time1_over1: string;
  break_time1_over2: string;
  break_time1_over3: string;
  break_time2: string;
  break_time2_over1: string;
  break_time2_over2: string;
  break_time2_over3: string;
  break_time3: string;
  break_time3_over1: string;
  break_time3_over2: string;
  break_time3_over3: string;
  break_time4: string;
  break_time4_over1: string;
  break_time4_over2: string;
  break_time4_over3: string;
  break_time5: string;
  break_time5_over1: string;
  break_time5_over2: string;
  break_time5_over3: string;
  break_time6: string;
  break_time6_over1: string;
  break_time6_over2: string;
  break_time6_over3: string;
  pop_up1: string;
  pop_up_id1: string;
  pop_up2: string;
  pop_up_id2: string;
  pop_up3: string;
  pop_up_id3: string;
  pop_up4: string;
  pop_up_id4: string;
  pop_up5: string;
  pop_up_id5: string;
  break_check: boolean;
  def_prediction: boolean;
}

const MemberEdit: React.FC = () => {
  const navigate = useNavigate();
  const { employee_no } = useParams<{ employee_no: string }>();
  const employeeNo = Number(employee_no);
  const [formData, setFormData] = useState<Member | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  useEffect(() => {
    const fetchMember = async () => {
      try {
        const response = await api.get<Member>(`/api/member_update/${employeeNo}/`);
        setFormData(response.data);
      } catch (err) {
        if (axios.isAxiosError(err)) {
          if (err.response?.status === 401) navigate("/login");
          else if (err.response?.status === 403) navigate("/");
          else setErrorMessage(err.response?.data.message);
        } else setErrorMessage("不明なエラーが発生しました。IT担当者に連絡してください。");
      } finally {
        setLoading(false);
      }
    };

    fetchMember();
  }, [employeeNo, navigate]);

  const handleChange = (
    event: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>
  ) => {
    const { name, value, type } = event.target;

    if (type === "checkbox") {
      const { checked } = event.target as HTMLInputElement;
      setFormData((prev) => {
        if (!prev) return prev;
        return {
          ...prev,
          [name]: checked,
        };
      });
    } else {
      setFormData((prev) => {
        if (!prev) return prev;
        return {
          ...prev,
          [name]: value,
        };
      });
    }
  };

  const handleSubmit = async (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    try {
      await api.put(`/api/member_update/${employeeNo}/`, formData);
      alert("データが更新されました！");
      navigate("/member-list");
    } catch (err) {
      if (axios.isAxiosError(err)) {
        if (err.response?.status === 401) navigate("/login");
        else setErrorMessage(err.response?.data.message);
      } else setErrorMessage("不明なエラーが発生しました。IT担当者に連絡してください。");
    }
  };

  if (loading) return <div><Loading isLoading={loading} /></div>;
  if (errorMessage) return <div>Error: {errorMessage}</div>;
  if (!formData) return <div>データが見つかりません</div>;

  return (
    <>
      <Loading isLoading={loading} />
      <div className={styles["member-edit-wrapper"]}>
        <h1 className={styles["h1-collar"]}>人員データ編集</h1>
        <nav className={styles["member-nav"]}>
          <Link to="/member-list">人員一覧</Link>
        </nav>

        {errorMessage && (
          <div role="alert">{errorMessage}</div>
        )}

        <form 
          onSubmit={handleSubmit}
          onKeyDown={(e) => {
            if (e.key === "Enter" && e.target instanceof HTMLInputElement && e.target.type !== "textarea") {
              e.preventDefault();
              (e.target as HTMLInputElement).blur();
            }
          }}
        >
          <div className={styles["search-bar"]}>
            <label htmlFor="employee_no">従業員番号:</label>
            <input
              type="number"
              id="employee_no"
              name="employee_no"
              value={formData.employee_no}
              onChange={handleChange}
            />

            <label htmlFor="name">氏名:</label>
            <input
              type="text"
              id="name"
              name="name"
              value={formData.name}
              onChange={handleChange}
            />

            <label htmlFor="shop">ショップ:</label>
            <ShopSelect
              name="shop"
              value={formData.shop}
              onChange={(event) => handleChange(event as ChangeEvent<HTMLSelectElement>)}
            />

            <div className={styles["switch-wrapper"]}>
              <label htmlFor="authority">権限:</label>
              <label className={styles["toggle-switch"]}>
                <input
                  type="checkbox"
                  id="authority"
                  name="authority"
                  checked={formData.authority}
                  onChange={handleChange}
                />
                <span className={styles["toggle-slider"]}></span>
              </label>
            </div>

            <div className={styles["switch-wrapper"]}>
              <label htmlFor="administrator">管理者権限:</label>
              <label className={styles["toggle-switch"]}>
                <input
                  type="checkbox"
                  id="administrator"
                  name="administrator"
                  checked={formData.administrator}
                  onChange={handleChange}
                />
                <span className={styles["toggle-slider"]}></span>
              </label>
            </div>
            <button type="submit" className="yellow_button">更新</button>
          </div>
        </form>
      </div>
    </>
  );
};

export default MemberEdit;